1: #!/usr/bin/env node
2: // 依赖安装兼容入口：优先使用 Bun（与 bun.lock 严格对齐，--frozen-lockfile 保证可复现）；
3: // 当运行环境没有 Bun 时回退到 npm，使 CI 在仅预装 Node 的 runner 上也能完成安装。
4: // 用法：node scripts/install-deps.mjs   （由 package.json 的 install-dependencies 调用）
5: import { spawnSync } from 'node:child_process';
6: import { existsSync } from 'node:fs';
7: import { fileURLToPath } from 'node:url';
8: import { dirname, join } from 'node:path';
9: 
10: const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
11: 
12: function hasCommand(cmd) {
13:   const probe = process.platform === 'win32'
14:     ? spawnSync('where', [cmd], { stdio: 'ignore' })
15:     : spawnSync('sh', ['-c', `command -v ${cmd}`], { stdio: 'ignore' });
16:   return probe.status === 0;
17: }
18: 
19: function run(cmd, args, cwd = ROOT) {
20:   console.log(`\n[install-deps] $ ${cmd} ${args.join(' ')}   (cwd=${cwd})`);
21:   const res = spawnSync(cmd, args, { stdio: 'inherit', cwd, shell: process.platform === 'win32' });
22:   return res.status ?? 1;
23: }
24: 
25: const hasBunLock = existsSync(join(ROOT, 'bun.lock')) || existsSync(join(ROOT, 'bun.lockb'));
26: const hasPkgLock = existsSync(join(ROOT, 'package-lock.json'));
27: const testingDir = join(ROOT, 'tools', 'testing');
28: 
29: let code;
30: if (hasCommand('bun')) {
31:   console.log('[install-deps] 检测到 Bun，使用 Bun 安装（--frozen-lockfile）');
32:   code = run('bun', hasBunLock ? ['install', '--frozen-lockfile'] : ['install']);
33: } else {
34:   console.log('[install-deps] 未检测到 Bun，回退到 npm 安装');
35:   // 1) 根项目安装。
36:   //    DCloud 系包存在 peer 版本偏差（如 @dcloudio/types 3.4.32 vs uni-app 期望 3.4.31），
37:   //    Bun 默认宽松解析可通过，npm 严格模式会 ERESOLVE 直接失败，故统一带 --legacy-peer-deps。
38:   const npmArgs = ['--no-audit', '--no-fund', '--legacy-peer-deps'];
39:   code = run('npm', [hasPkgLock ? 'ci' : 'install', ...npmArgs]);
40:   if (code !== 0 && hasPkgLock) {
41:     console.warn('[install-deps] npm ci 失败，改用 npm install 重试');
42:     code = run('npm', ['install', ...npmArgs]);
43:   }
44:   if (code !== 0) process.exit(code);
45: 
46:   // 2) 测试工具链独立安装。
47:   //    测试工具链需要 vite@8 与 vitest@5，而应用根使用 vite@5（uni-app 要求），版本冲突。
48:   //    Bun 通过 workspace 各自嵌套 node_modules 隔离；npm 在 workspace 模式下会强制把
49:   //    vitest 提升到根目录，导致 vitest 解析到根的 vite@5 而启动失败。
50:   //    这里用 --workspaces=false 让 npm 把 tools/testing 当作独立项目安装，得到自带的
51:   //    vite@8 + vitest@5；同时因目录仍位于仓库内，vue 等依赖可向上解析到根 node_modules。
52:   //    注意：不改动根 package.json 的 workspaces 字段，从而不影响 Bun / bun.lock 的可复现安装。
53:   if (existsSync(join(testingDir, 'package.json'))) {
54:     console.log('[install-deps] 安装测试工具链（独立 node_modules，避免 vite 版本冲突）');
55:     const testCode = run('npm', ['install', ...npmArgs, '--workspaces=false'], testingDir);
56:     if (testCode !== 0) {
57:       console.warn('[install-deps] 测试工具链安装失败（不影响应用构建）');
58:     }
59:   }
60: }
61: 
62: process.exit(code);

